if (document.getElementById('tutorial-lightbox-styles')) return;
const style = document.createElement('style');
style.id = 'tutorial-lightbox-styles';
style.textContent = `
  /* ── Lightbox Overlay ── */
  #tut-lightbox-overlay {
    display: none;
    position: fixed;
    inset: 0;
    z-index: 999999;
    background: rgba(0,0,0,0.93);
    flex-direction: column;
    align-items: center;
    justify-content: center;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
    animation: tutFadeIn 0.22s ease;
  }
  #tut-lightbox-overlay.active { display: flex; }
  @keyframes tutFadeIn { from { opacity:0 } to { opacity:1 } }

  /* ── Top bar ── */
  #tut-lb-topbar {
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 52px;
    background: linear-gradient(180deg,rgba(0,0,0,0.85) 0%,transparent 100%);
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0 18px;
    gap: 12px;
    z-index: 2;
  }
  #tut-lb-counter {
    color: rgba(255,255,255,0.75);
    font-size: 13px;
    font-weight: 600;
    letter-spacing: .04em;
  }
  #tut-lb-title {
    flex: 1;
    color: #fff;
    font-size: 13px;
    font-weight: 600;
    text-align: center;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
  }
  #tut-lb-close {
    background: rgba(255,255,255,0.12);
    border: none;
    color: #fff;
    font-size: 22px;
    line-height: 1;
    cursor: pointer;
    width: 36px; height: 36px;
    border-radius: 50%;
    display: flex; align-items: center; justify-content: center;
    transition: background .15s;
  }
  #tut-lb-close:hover { background: rgba(255,80,80,0.65); }

  /* ── Image area ── */
  #tut-lb-stage {
    position: relative;
    display: flex;
    align-items: center;
    justify-content: center;
    max-width: calc(100vw - 120px);
    max-height: calc(100vh - 180px);
    cursor: zoom-in;
  }
  #tut-lb-stage.zoomed { cursor: zoom-out; }
  #tut-lb-img {
    max-width: 100%;
    max-height: calc(100vh - 180px);
    object-fit: contain;
    border-radius: 6px;
    box-shadow: 0 8px 60px rgba(0,0,0,0.7);
    transition: transform 0.28s cubic-bezier(.4,0,.2,1);
    transform-origin: center center;
    display: block;
    user-select: none;
  }
  #tut-lb-stage.zoomed #tut-lb-img {
    transform: scale(2.2);
    cursor: zoom-out;
  }

  /* ── Annotation badge ── */
  #tut-lb-annotation {
    position: absolute;
    bottom: -8px;
    left: 50%;
    transform: translateX(-50%) translateY(100%);
    background: linear-gradient(135deg,#e63950,#c0203a);
    color: #fff;
    font-size: 12px;
    font-weight: 700;
    padding: 5px 13px;
    border-radius: 20px;
    letter-spacing: .04em;
    white-space: nowrap;
    pointer-events: none;
    box-shadow: 0 3px 12px rgba(230,57,80,.55);
    display: none;
  }

  /* ── Click-target pulse overlay ── */
  .tut-click-pulse {
    position: absolute;
    border: 3px solid #ffce00;
    border-radius: 8px;
    box-shadow: 0 0 0 0 rgba(255,206,0,.6);
    animation: tutPulse 1.6s ease-in-out infinite;
    pointer-events: none;
    z-index: 10;
  }
  @keyframes tutPulse {
    0%   { box-shadow: 0 0 0 0 rgba(255,206,0,.6); }
    60%  { box-shadow: 0 0 0 12px rgba(255,206,0,0); }
    100% { box-shadow: 0 0 0 0 rgba(255,206,0,0); }
  }

  /* ── Caption / annotation panel ── */
  #tut-lb-caption-panel {
    position: absolute;
    bottom: 0; left: 0; right: 0;
    background: linear-gradient(0deg,rgba(0,0,0,0.88) 0%,transparent 100%);
    padding: 42px 24px 20px;
    text-align: center;
    pointer-events: none;
  }
  #tut-lb-caption-text {
    color: #e8e8e8;
    font-size: 14.5px;
    line-height: 1.55;
    max-width: 700px;
    margin: 0 auto;
  }
  #tut-lb-caption-text strong {
    color: #ffce00;
  }
  #tut-lb-hint {
    color: rgba(255,255,255,0.42);
    font-size: 11.5px;
    margin-top: 7px;
  }

  /* ── Nav arrows ── */
  .tut-lb-nav {
    position: absolute;
    top: 50%;
    transform: translateY(-50%);
    background: rgba(255,255,255,0.10);
    border: none;
    color: #fff;
    font-size: 28px;
    width: 52px; height: 52px;
    border-radius: 50%;
    cursor: pointer;
    display: flex; align-items: center; justify-content: center;
    transition: background .15s, transform .15s;
    z-index: 5;
    backdrop-filter: blur(4px);
    user-select: none;
  }
  .tut-lb-nav:hover { background: rgba(255,255,255,0.25); transform: translateY(-50%) scale(1.08); }
  #tut-lb-prev { left: 14px; }
  #tut-lb-next { right: 14px; }
  .tut-lb-nav:disabled { opacity: .2; cursor: default; }
  .tut-lb-nav:disabled:hover { background: rgba(255,255,255,0.10); transform: translateY(-50%) scale(1); }

  /* ── Thumbnail strip ── */
  #tut-lb-thumbstrip {
    position: absolute;
    bottom: 0; left: 0; right: 0;
    height: 68px;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 7px;
    padding: 0 12px 8px;
    overflow-x: auto;
    scrollbar-width: none;
    z-index: 3;
  }
  #tut-lb-thumbstrip::-webkit-scrollbar { display: none; }
  .tut-lb-thumb {
    width: 52px; height: 52px;
    object-fit: cover;
    border-radius: 5px;
    border: 2px solid transparent;
    opacity: 0.55;
    cursor: pointer;
    transition: opacity .15s, border-color .15s, transform .15s;
    flex-shrink: 0;
  }
  .tut-lb-thumb:hover { opacity: 0.85; transform: scale(1.06); }
  .tut-lb-thumb.active { opacity: 1; border-color: #ffce00; transform: scale(1.1); }

  /* ── Zoom badge ── */
  #tut-lb-zoom-badge {
    position: absolute;
    top: 62px; right: 16px;
    background: rgba(255,255,255,0.13);
    color: rgba(255,255,255,0.7);
    font-size: 11px;
    padding: 4px 10px;
    border-radius: 12px;
    pointer-events: none;
    z-index: 3;
    backdrop-filter: blur(3px);
  }

  /* ── "OPEN LIGHTBOX" trigger badge on images ── */
  .tut-img-trigger {
    position: relative;
    cursor: zoom-in !important;
  }
  .tut-img-trigger::after {
    content: '🔍 View Full-Screen';
    position: absolute;
    bottom: 6px; left: 50%;
    transform: translateX(-50%);
    background: rgba(0,0,0,0.72);
    color: #fff;
    font-size: 11px;
    font-weight: 700;
    padding: 4px 10px;
    border-radius: 12px;
    white-space: nowrap;
    opacity: 0;
    transition: opacity .2s;
    pointer-events: none;
    z-index: 5;
    letter-spacing: .03em;
  }
  .tut-img-trigger:hover::after { opacity: 1; }
`;
document.head.appendChild(style);

if (document.getElementById('tut-lightbox-overlay')) return;

/* ── Build overlay DOM ── */
const ov = document.createElement('div');
ov.id = 'tut-lightbox-overlay';
ov.innerHTML = `
  <div id="tut-lb-topbar">
    <span id="tut-lb-counter"></span>
    <span id="tut-lb-title"></span>
    <button id="tut-lb-close" title="Close (Esc)">&#x2715;</button>
  </div>
  <button class="tut-lb-nav" id="tut-lb-prev" title="Previous">&#8592;</button>
  <div id="tut-lb-stage">
    <img id="tut-lb-img" src="" alt="" />
    <span id="tut-lb-annotation"></span>
  </div>
  <button class="tut-lb-nav" id="tut-lb-next" title="Next">&#8594;</button>
  <div id="tut-lb-caption-panel">
    <div id="tut-lb-caption-text"></div>
    <div id="tut-lb-hint">Click image to zoom &middot; Arrow keys to navigate &middot; Esc to close</div>
  </div>
  <div id="tut-lb-zoom-badge">Click to zoom</div>
  <div id="tut-lb-thumbstrip"></div>
`;
document.body.appendChild(ov);

function getHiResUrl(src) {
  if (!src) return src;
  return src.replace(/\/scale-to-width-down\/\d+/, '');
}

function buildImageList() {
  const imgs = [];
  document.querySelectorAll('.wikia-gallery-item').forEach(function(item) {
    const img = item.querySelector('img.thumbimage');
    const captionEl = item.querySelector('.lightbox-caption');
    if (!img) return;
    const rawSrc = img.src || img.getAttribute('data-src') || '';
    imgs.push({ src: rawSrc, hiResSrc: getHiResUrl(rawSrc), alt: img.alt || '', caption: captionEl ? captionEl.textContent.trim() : (img.alt || ''), el: img });
  });
  document.querySelectorAll('figure.thumb img.thumbimage[data-relevant="1"]').forEach(function(img) {
    const rawSrc = img.src || img.getAttribute('data-src') || '';
    const figcap = img.closest('figure') ? img.closest('figure').querySelector('.thumbcaption') : null;
    imgs.push({ src: rawSrc, hiResSrc: getHiResUrl(rawSrc), alt: img.alt || '', caption: figcap ? figcap.textContent.trim() : (img.alt || ''), el: img });
  });
  return imgs;
}

function buildAnnotation(caption) {
  const lower = caption.toLowerCase();
  const hints = [];
  if (lower.includes('tap') || lower.includes('click') || lower.includes('select')) {
    const match = caption.match(/"([^"]+)"/);
    if (match) hints.push('\uD83D\uDC46 Tap / Click: "' + match[1] + '"');
  }
  if (lower.includes('top right'))   hints.push('\uD83D\uDCCD Location: Top-right corner');
  if (lower.includes('top left'))    hints.push('\uD83D\uDCCD Location: Top-left corner');
  if (lower.includes('mobile'))      hints.push('\uD83D\uDCF1 Mobile UI shown');
  if (lower.includes('desktop'))     hints.push('\uD83D\uDDA5\uFE0F Desktop UI shown');
  if (lower.includes('scroll'))      hints.push('\u2195\uFE0F Scroll to find this');
  if (lower.includes('register') || lower.includes('sign up')) hints.push('\u2705 Registration step');
  if (lower.includes('appearance') || lower.includes('theme')) hints.push('\uD83C\uDFA8 Appearance setting');
  if (lower.includes('preference') || lower.includes('setting')) hints.push('\u2699\uFE0F Settings / Preferences');
  return hints.join('  \u00B7  ');
}

let images = [];
let current = 0;
let zoomed = false;

const lbImg   = document.getElementById('tut-lb-img');
const lbTitle = document.getElementById('tut-lb-title');
const lbCount = document.getElementById('tut-lb-counter');
const lbCap   = document.getElementById('tut-lb-caption-text');
const lbAnno  = document.getElementById('tut-lb-annotation');
const lbStage = document.getElementById('tut-lb-stage');
const lbPrev  = document.getElementById('tut-lb-prev');
const lbNext  = document.getElementById('tut-lb-next');
const lbStrip = document.getElementById('tut-lb-thumbstrip');
const lbZoom  = document.getElementById('tut-lb-zoom-badge');

function showSlide(idx) {
  current = Math.max(0, Math.min(idx, images.length - 1));
  const item = images[current];
  zoomed = false;
  lbStage.classList.remove('zoomed');
  lbImg.style.transform = '';
  lbImg.src = item.src;
  lbImg.alt = item.alt;
  const hiRes = new Image();
  hiRes.onload = function() { lbImg.src = hiRes.src; };
  hiRes.src = item.hiResSrc;
  lbCount.textContent = (current + 1) + ' / ' + images.length;
  lbTitle.textContent = item.alt || 'Tutorial Screenshot';
  lbZoom.textContent = 'Click to zoom';
  let capHtml = item.caption
    .replace(/("([^"]+)")/g, '<strong>$1</strong>')
    .replace(/\b(tap|click|select|register|sign up|appearance|theme|preferences?|settings?)\b/gi, '<strong>$1</strong>');
  lbCap.innerHTML = capHtml;
  const anno = buildAnnotation(item.caption);
  lbAnno.textContent = anno;
  lbAnno.style.display = anno ? 'block' : 'none';
  lbPrev.disabled = (current === 0);
  lbNext.disabled = (current === images.length - 1);
  const thumbs = lbStrip.querySelectorAll('.tut-lb-thumb');
  thumbs.forEach(function(t, i) { t.classList.toggle('active', i === current); });
  if (thumbs[current]) thumbs[current].scrollIntoView({ inline: 'center', block: 'nearest', behavior: 'smooth' });
}

function openLightbox(idx) {
  images = buildImageList();
  if (!images.length) return;
  lbStrip.innerHTML = '';
  images.forEach(function(item, i) {
    const t = document.createElement('img');
    t.src = item.src;
    t.alt = item.alt;
    t.className = 'tut-lb-thumb';
    t.addEventListener('click', function(e) { e.stopPropagation(); showSlide(i); });
    lbStrip.appendChild(t);
  });
  showSlide(idx);
  ov.classList.add('active');
  document.body.style.overflow = 'hidden';
}

function closeLightbox() {
  ov.classList.remove('active');
  document.body.style.overflow = '';
  zoomed = false;
  lbStage.classList.remove('zoomed');
}

lbStage.addEventListener('click', function() {
  zoomed = !zoomed;
  lbStage.classList.toggle('zoomed', zoomed);
  lbZoom.textContent = zoomed ? 'Click to zoom out' : 'Click to zoom';
});

lbPrev.addEventListener('click', function(e) { e.stopPropagation(); showSlide(current - 1); });
lbNext.addEventListener('click', function(e) { e.stopPropagation(); showSlide(current + 1); });
document.getElementById('tut-lb-close').addEventListener('click', closeLightbox);
ov.addEventListener('click', function(e) { if (e.target === ov) closeLightbox(); });

document.addEventListener('keydown', function(e) {
  if (!ov.classList.contains('active')) return;
  if (e.key === 'Escape')     { closeLightbox(); }
  if (e.key === 'ArrowLeft')  { showSlide(current - 1); }
  if (e.key === 'ArrowRight') { showSlide(current + 1); }
  if (e.key === ' ')          { e.preventDefault(); lbStage.click(); }
});

function attachTriggers() {
  const items = buildImageList();
  items.forEach(function(item, idx) {
    if (!item.el) return;
    const wrapper = item.el.closest('.gallery-image-wrapper') || item.el.closest('figure') || item.el;
    if (wrapper._tutLbAttached) return;
    wrapper._tutLbAttached = true;
    wrapper.classList.add('tut-img-trigger');
    const anchor = wrapper.tagName === 'A' ? wrapper : wrapper.querySelector('a');
    if (anchor) {
      anchor.addEventListener('click', function(e) { e.preventDefault(); e.stopPropagation(); openLightbox(idx); });
    } else {
      wrapper.addEventListener('click', function(e) { e.preventDefault(); e.stopPropagation(); openLightbox(idx); });
    }
    item.el.style.cursor = 'zoom-in';
  });
}

attachTriggers();
